/**
 * Safe output planning and application for generated files.
 *
 * Generation is deliberately split into a read-only planning phase and a
 * transactional apply phase. The ownership manifest is the authority for
 * pruning and modified-file detection; directory scans are never used to
 * decide what may be deleted.
 */
import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';

import type { GeneratedFile } from '../codegen';

export type { GeneratedFile };

export const GENERATED_FILES_MANIFEST = '.constructive-codegen-manifest.json';

const MANIFEST_VERSION = 1;
const GENERATOR_NAME = '@constructive-io/graphql-codegen';
const LEGACY_GENERATED_MARKERS = [
  '@generated by @constructive-io/graphql-codegen',
  '@constructive-io/graphql-codegen - DO NOT EDIT',
];

interface ManifestFileEntry {
  sha256: string;
}

export interface GeneratedFilesManifest {
  version: 1;
  generator: typeof GENERATOR_NAME;
  files: Record<string, ManifestFileEntry>;
}

export type FileChangeAction =
  | 'create'
  | 'update'
  | 'delete'
  | 'unchanged'
  | 'conflict';

export interface FileChange {
  /** POSIX path relative to the output directory. */
  path: string;
  absolutePath: string;
  action: FileChangeAction;
  previousHash?: string;
  generatedHash?: string;
  reason?:
    | 'new-generated-file'
    | 'generated-content-changed'
    | 'generated-file-removed'
    | 'generated-content-unchanged'
    | 'modified-generated-file'
    | 'unowned-existing-file'
    | 'legacy-generated-file'
    | 'retained-owned-file'
    | 'ownership-manifest';
}

export interface GenerationPlan {
  version: 1;
  outputDir: string;
  manifestPath: string;
  fingerprint: string;
  changes: FileChange[];
}

/** Result of planning or writing files. */
export interface WriteResult {
  success: boolean;
  filesWritten?: string[];
  filesRemoved?: string[];
  errors?: string[];
  /** Non-fatal cleanup or recovery information. */
  warnings?: string[];
  /** Retained transaction directory when rollback or cleanup was incomplete. */
  recoveryPath?: string;
  rollbackErrors?: string[];
  plan?: GenerationPlan;
  planFingerprint?: string;
}

export interface WriteOptions {
  /** Show progress output (default: true). */
  showProgress?: boolean;
  /** Format TypeScript files with oxfmt before planning (default: true). */
  formatFiles?: boolean;
  /** Remove previously owned files absent from the current file set. */
  pruneStaleFiles?: boolean;
  /** Compute and return the complete plan without mutating the filesystem. */
  dryRun?: boolean;
  /** Permit replacing or deleting owned files changed since generation. */
  overwriteModifiedGenerated?: boolean;
  /** Required confirmation paired with overwriteModifiedGenerated. */
  confirmOverwrite?: boolean;
  /** Known legacy generated paths that predate the ownership manifest. */
  adoptUnownedPaths?: string[];
  /** Delete the ownership manifest when the desired owned file set is empty. */
  removeManifestWhenEmpty?: boolean;
}

export interface GeneratedFileWriteJob {
  files: GeneratedFile[];
  outputDir: string;
  options?: Omit<WriteOptions, 'dryRun'>;
}

export interface WriteBatchResult {
  success: boolean;
  results: WriteResult[];
  errors?: string[];
}

export interface WriteBatchOptions extends Pick<
  WriteOptions,
  'dryRun' | 'showProgress'
> {
  /** Cancellation is honored until the coordinated commit begins. */
  signal?: AbortSignal;
}

interface PreparedFile {
  relativePath: string;
  absolutePath: string;
  content: string;
  hash: string;
}

interface PreparedPlan {
  publicPlan: GenerationPlan;
  desiredFiles: Map<string, PreparedFile>;
  manifestContent?: string;
  manifestChanged: boolean;
  removeOutputDirWhenEmpty: boolean;
}

type OxfmtFormatFn = (
  fileName: string,
  sourceText: string,
  options?: Record<string, unknown>
) => Promise<{ code: string; errors: unknown[] }>;

function hashContent(content: string | Buffer): string {
  return createHash('sha256').update(content).digest('hex');
}

function isPathInside(parent: string, candidate: string): boolean {
  const relative = path.relative(parent, candidate);
  return (
    relative === '' ||
    (!relative.startsWith(`..${path.sep}`) &&
      relative !== '..' &&
      !path.isAbsolute(relative))
  );
}

/**
 * Resolve an output directory through the deepest existing ancestor. This lets
 * an explicitly symlinked cwd/output root work while giving all descendant
 * containment checks one canonical boundary.
 */
function canonicalizeOutputDir(outputDir: string): string {
  const absolute = path.resolve(outputDir);
  const missingSegments: string[] = [];
  let existing = absolute;

  while (true) {
    try {
      fs.lstatSync(existing);
      break;
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== 'ENOENT' && code !== 'ENOTDIR') throw error;
      const parent = path.dirname(existing);
      if (parent === existing) throw error;
      missingSegments.unshift(path.basename(existing));
      existing = parent;
    }
  }

  const canonicalAncestor = fs.realpathSync.native(existing);
  const existingStat = fs.statSync(canonicalAncestor);
  if (missingSegments.length === 0 && !existingStat.isDirectory()) {
    throw new Error(`Generated output path is not a directory: ${absolute}`);
  }
  return path.join(canonicalAncestor, ...missingSegments);
}

/** Refuse any symlink below the canonical output root. */
function assertContainedPath(outputDir: string, candidate: string): void {
  if (!isPathInside(outputDir, candidate)) {
    throw new Error(`Generated file escapes output directory: ${candidate}`);
  }

  let current = candidate;
  while (current !== outputDir) {
    try {
      if (fs.lstatSync(current).isSymbolicLink()) {
        throw new Error(
          `Generated file path traverses a symlink below the output directory: ${current}`
        );
      }
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== 'ENOENT' && code !== 'ENOTDIR') throw error;
    }
    const parent = path.dirname(current);
    if (parent === current) {
      throw new Error(`Generated file escapes output directory: ${candidate}`);
    }
    current = parent;
  }
}

function normalizeRelativePath(filePath: string): string {
  if (!filePath || path.isAbsolute(filePath)) {
    throw new Error(`Generated file path must be relative: ${filePath}`);
  }

  const normalized = filePath.replace(/\\/g, '/');
  const segments = normalized.split('/');
  if (
    segments.some(
      (segment) => segment === '' || segment === '.' || segment === '..'
    )
  ) {
    throw new Error(`Generated file path is unsafe: ${filePath}`);
  }

  const relativePath = path.posix.normalize(normalized);
  if (
    relativePath === GENERATED_FILES_MANIFEST ||
    relativePath.startsWith('../')
  ) {
    throw new Error(`Generated file path is reserved or unsafe: ${filePath}`);
  }

  return relativePath;
}

function isManifest(value: unknown): value is GeneratedFilesManifest {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<GeneratedFilesManifest>;
  if (
    candidate.version !== MANIFEST_VERSION ||
    candidate.generator !== GENERATOR_NAME ||
    !candidate.files ||
    typeof candidate.files !== 'object' ||
    Array.isArray(candidate.files)
  ) {
    return false;
  }

  return Object.entries(candidate.files).every(([filePath, entry]) => {
    try {
      if (normalizeRelativePath(filePath) !== filePath) return false;
    } catch {
      return false;
    }
    return (
      !!entry &&
      typeof entry === 'object' &&
      typeof entry.sha256 === 'string' &&
      /^[a-f0-9]{64}$/.test(entry.sha256)
    );
  });
}

function readManifest(manifestPath: string): {
  manifest: GeneratedFilesManifest;
  content?: string;
} {
  if (!fs.existsSync(manifestPath)) {
    return {
      manifest: {
        version: MANIFEST_VERSION,
        generator: GENERATOR_NAME,
        files: {},
      },
    };
  }

  const content = fs.readFileSync(manifestPath, 'utf8');
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    throw new Error(
      `Generated ownership manifest is not valid JSON: ${manifestPath}`
    );
  }

  if (!isManifest(parsed)) {
    throw new Error(
      `Generated ownership manifest has an unsupported or invalid shape: ${manifestPath}`
    );
  }

  return { manifest: parsed, content };
}

function isLegacyGenerated(content: Buffer): boolean {
  const prefix = content.subarray(0, 4096).toString('utf8');
  return LEGACY_GENERATED_MARKERS.some((marker) => prefix.includes(marker));
}

async function getOxfmtFormat(): Promise<OxfmtFormatFn | null> {
  try {
    const oxfmt = await import('oxfmt');
    return oxfmt.format;
  } catch {
    return null;
  }
}

async function formatFileContent(
  fileName: string,
  content: string,
  formatFn: OxfmtFormatFn
): Promise<string> {
  try {
    const result = await formatFn(fileName, content, {
      singleQuote: true,
      trailingComma: 'es5',
      tabWidth: 2,
      semi: true,
    });
    return result.code;
  } catch {
    return content;
  }
}

function createManifestContent(
  files: Record<string, ManifestFileEntry>
): string {
  const sortedFiles = Object.fromEntries(
    Object.entries(files).sort(([left], [right]) => left.localeCompare(right))
  );
  return `${JSON.stringify(
    {
      version: MANIFEST_VERSION,
      generator: GENERATOR_NAME,
      files: sortedFiles,
    } satisfies GeneratedFilesManifest,
    null,
    2
  )}\n`;
}

function fingerprintChanges(
  changes: FileChange[],
  manifestContent: string | undefined
): string {
  const canonical = changes
    .map((change) => ({
      path: change.path,
      action: change.action,
      previousHash: change.previousHash,
      generatedHash: change.generatedHash,
      reason: change.reason,
    }))
    .sort((left, right) => left.path.localeCompare(right.path));
  return hashContent(
    JSON.stringify({
      changes: canonical,
      manifestHash:
        manifestContent === undefined ? null : hashContent(manifestContent),
    })
  );
}

async function prepareGenerationPlan(
  files: GeneratedFile[],
  outputDir: string,
  options: WriteOptions
): Promise<PreparedPlan> {
  const {
    formatFiles = true,
    pruneStaleFiles = false,
    overwriteModifiedGenerated = false,
    confirmOverwrite = false,
    adoptUnownedPaths = [],
    removeManifestWhenEmpty = false,
  } = options;

  if (overwriteModifiedGenerated && !confirmOverwrite) {
    throw new Error(
      'overwriteModifiedGenerated requires explicit confirmOverwrite confirmation'
    );
  }

  const resolvedOutputDir = canonicalizeOutputDir(outputDir);
  const manifestPath = path.join(resolvedOutputDir, GENERATED_FILES_MANIFEST);
  assertContainedPath(resolvedOutputDir, manifestPath);
  const { manifest, content: previousManifestContent } =
    readManifest(manifestPath);
  const desiredFiles = new Map<string, PreparedFile>();
  const explicitlyAdoptedPaths = new Set(
    adoptUnownedPaths.map(normalizeRelativePath)
  );
  const formatFn = formatFiles ? await getOxfmtFormat() : null;

  for (const file of files) {
    const relativePath = normalizeRelativePath(file.path);
    if (desiredFiles.has(relativePath)) {
      throw new Error(`Duplicate generated file path: ${relativePath}`);
    }

    const content =
      formatFn && relativePath.endsWith('.ts')
        ? await formatFileContent(relativePath, file.content, formatFn)
        : file.content;
    desiredFiles.set(relativePath, {
      relativePath,
      absolutePath: path.join(resolvedOutputDir, ...relativePath.split('/')),
      content,
      hash: hashContent(content),
    });
    assertContainedPath(
      resolvedOutputDir,
      path.join(resolvedOutputDir, ...relativePath.split('/'))
    );
  }

  const changes: FileChange[] = [];
  const nextManifestFiles: Record<string, ManifestFileEntry> = {};

  for (const desired of desiredFiles.values()) {
    const previousEntry = manifest.files[desired.relativePath];
    let existing: Buffer | undefined;
    try {
      existing = fs.readFileSync(desired.absolutePath);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    }

    if (!existing) {
      changes.push({
        path: desired.relativePath,
        absolutePath: desired.absolutePath,
        action: 'create',
        generatedHash: desired.hash,
        reason: 'new-generated-file',
      });
      nextManifestFiles[desired.relativePath] = { sha256: desired.hash };
      continue;
    }

    const existingHash = hashContent(existing);
    const isExplicitlyAdopted = explicitlyAdoptedPaths.has(
      desired.relativePath
    );
    const isRecognizedLegacyFile = isLegacyGenerated(existing);
    if (!previousEntry && !isRecognizedLegacyFile && !isExplicitlyAdopted) {
      changes.push({
        path: desired.relativePath,
        absolutePath: desired.absolutePath,
        action: 'conflict',
        previousHash: existingHash,
        generatedHash: desired.hash,
        reason: 'unowned-existing-file',
      });
      continue;
    }

    if (existingHash === desired.hash) {
      changes.push({
        path: desired.relativePath,
        absolutePath: desired.absolutePath,
        action: 'unchanged',
        previousHash: existingHash,
        generatedHash: desired.hash,
        reason: 'generated-content-unchanged',
      });
      nextManifestFiles[desired.relativePath] = { sha256: desired.hash };
      continue;
    }

    const modifiedOwnedFile =
      !!previousEntry && existingHash !== previousEntry.sha256;
    const conflict = modifiedOwnedFile;

    if (conflict && !overwriteModifiedGenerated) {
      changes.push({
        path: desired.relativePath,
        absolutePath: desired.absolutePath,
        action: 'conflict',
        previousHash: existingHash,
        generatedHash: desired.hash,
        reason: modifiedOwnedFile
          ? 'modified-generated-file'
          : 'modified-generated-file',
      });
    } else {
      changes.push({
        path: desired.relativePath,
        absolutePath: desired.absolutePath,
        action: 'update',
        previousHash: existingHash,
        generatedHash: desired.hash,
        reason: modifiedOwnedFile
          ? 'modified-generated-file'
          : !previousEntry
            ? 'legacy-generated-file'
            : 'generated-content-changed',
      });
    }
    nextManifestFiles[desired.relativePath] = { sha256: desired.hash };
  }

  for (const [relativePath, previousEntry] of Object.entries(manifest.files)) {
    if (desiredFiles.has(relativePath)) continue;
    const absolutePath = path.join(
      resolvedOutputDir,
      ...relativePath.split('/')
    );
    assertContainedPath(resolvedOutputDir, absolutePath);
    let existing: Buffer | undefined;
    try {
      existing = fs.readFileSync(absolutePath);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    }
    if (!existing) continue;

    const existingHash = hashContent(existing);
    if (!pruneStaleFiles) {
      changes.push({
        path: relativePath,
        absolutePath,
        action: 'unchanged',
        previousHash: existingHash,
        reason: 'retained-owned-file',
      });
      nextManifestFiles[relativePath] = previousEntry;
      continue;
    }

    const modified = existingHash !== previousEntry.sha256;
    if (modified && !overwriteModifiedGenerated) {
      changes.push({
        path: relativePath,
        absolutePath,
        action: 'conflict',
        previousHash: existingHash,
        reason: 'modified-generated-file',
      });
      nextManifestFiles[relativePath] = previousEntry;
    } else {
      changes.push({
        path: relativePath,
        absolutePath,
        action: 'delete',
        previousHash: existingHash,
        reason: modified ? 'modified-generated-file' : 'generated-file-removed',
      });
    }
  }

  changes.sort((left, right) => left.path.localeCompare(right.path));
  const manifestContent =
    removeManifestWhenEmpty && Object.keys(nextManifestFiles).length === 0
      ? undefined
      : createManifestContent(nextManifestFiles);
  const manifestChanged = previousManifestContent !== manifestContent;
  changes.push({
    path: GENERATED_FILES_MANIFEST,
    absolutePath: manifestPath,
    action: manifestChanged
      ? manifestContent === undefined
        ? 'delete'
        : previousManifestContent === undefined
          ? 'create'
          : 'update'
      : 'unchanged',
    previousHash:
      previousManifestContent === undefined
        ? undefined
        : hashContent(previousManifestContent),
    generatedHash:
      manifestContent === undefined ? undefined : hashContent(manifestContent),
    reason: 'ownership-manifest',
  });

  const publicPlan: GenerationPlan = {
    version: 1,
    outputDir: resolvedOutputDir,
    manifestPath,
    fingerprint: fingerprintChanges(changes, manifestContent),
    changes,
  };

  return {
    publicPlan,
    desiredFiles,
    manifestContent,
    manifestChanged,
    removeOutputDirWhenEmpty: removeManifestWhenEmpty,
  };
}

/**
 * Compute a complete generation plan without mutating the target filesystem.
 */
export async function planGeneratedFiles(
  files: GeneratedFile[],
  outputDir: string,
  options: Omit<WriteOptions, 'dryRun' | 'showProgress'> = {}
): Promise<GenerationPlan> {
  return (await prepareGenerationPlan(files, outputDir, options)).publicPlan;
}

function removeEmptyParents(startDir: string, stopDir: string): void {
  let current = startDir;
  while (current !== stopDir && current.startsWith(`${stopDir}${path.sep}`)) {
    try {
      fs.rmdirSync(current);
    } catch {
      return;
    }
    current = path.dirname(current);
  }
}

interface CommittedChange {
  change: FileChange;
  backupCreated: boolean;
  targetWritten: boolean;
}

interface PlanTransaction {
  prepared: PreparedPlan;
  applicableChanges: FileChange[];
  transactionRoot: string;
  stagedRoot: string;
  backupRoot: string;
  committed: CommittedChange[];
  written: string[];
  removed: string[];
  manifestBackupCreated: boolean;
  manifestPublished: boolean;
}

function conflictErrors(plan: GenerationPlan): string[] {
  return plan.changes
    .filter((change) => change.action === 'conflict')
    .map(
      (conflict) =>
        `${conflict.reason === 'unowned-existing-file' ? 'Refusing to overwrite unowned file' : 'Generated file was modified'}: ${conflict.absolutePath}`
    );
}

function createPlanTransaction(prepared: PreparedPlan): PlanTransaction {
  const outputParent = path.dirname(prepared.publicPlan.outputDir);
  fs.mkdirSync(outputParent, { recursive: true });
  const transactionRoot = fs.mkdtempSync(
    path.join(
      outputParent,
      `.${path.basename(prepared.publicPlan.outputDir)}.codegen-transaction-`
    )
  );
  return {
    prepared,
    applicableChanges: prepared.publicPlan.changes.filter(
      (change) =>
        change.path !== GENERATED_FILES_MANIFEST &&
        (change.action === 'create' ||
          change.action === 'update' ||
          change.action === 'delete')
    ),
    transactionRoot,
    stagedRoot: path.join(transactionRoot, 'staged'),
    backupRoot: path.join(transactionRoot, 'backup'),
    committed: [],
    written: [],
    removed: [],
    manifestBackupCreated: false,
    manifestPublished: false,
  };
}

function stagePlan(transaction: PlanTransaction): void {
  const { prepared, applicableChanges, stagedRoot } = transaction;
  for (const change of applicableChanges) {
    if (change.action === 'delete') continue;
    const desired = prepared.desiredFiles.get(change.path);
    if (!desired) {
      throw new Error(`Missing prepared content for ${change.path}`);
    }
    const stagedPath = path.join(stagedRoot, ...change.path.split('/'));
    fs.mkdirSync(path.dirname(stagedPath), { recursive: true });
    fs.writeFileSync(stagedPath, desired.content, 'utf8');
  }
  if (prepared.manifestChanged && prepared.manifestContent !== undefined) {
    const stagedManifestPath = path.join(stagedRoot, GENERATED_FILES_MANIFEST);
    fs.mkdirSync(path.dirname(stagedManifestPath), { recursive: true });
    fs.writeFileSync(stagedManifestPath, prepared.manifestContent, {
      encoding: 'utf8',
      mode: 0o600,
    });
  }
}

function readOptionalHash(filePath: string): string | undefined {
  try {
    return hashContent(fs.readFileSync(filePath));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
    throw error;
  }
}

function assertPlanStillCurrent(transaction: PlanTransaction): void {
  const { publicPlan } = transaction.prepared;
  const currentOutputDir = canonicalizeOutputDir(publicPlan.outputDir);
  if (currentOutputDir !== publicPlan.outputDir) {
    throw new Error(
      `Generated output path changed after planning: ${publicPlan.outputDir}`
    );
  }

  for (const change of publicPlan.changes) {
    assertContainedPath(publicPlan.outputDir, change.absolutePath);
    const observedHash = readOptionalHash(change.absolutePath);
    if (observedHash !== change.previousHash) {
      throw new Error(
        `Generated output changed after planning: ${change.absolutePath}`
      );
    }
  }
}

function commitPlanFiles(
  transaction: PlanTransaction,
  showProgress: boolean,
  progress: { current: number; total: number }
): void {
  const { prepared, applicableChanges, backupRoot, stagedRoot } = transaction;
  fs.mkdirSync(prepared.publicPlan.outputDir, { recursive: true });

  for (const change of applicableChanges) {
    progress.current += 1;
    if (
      showProgress &&
      (progress.current === 1 ||
        progress.current === progress.total ||
        progress.current % 100 === 0)
    ) {
      console.log(
        `Applying generated files: ${progress.current}/${progress.total}`
      );
    }

    const targetPath = change.absolutePath;
    let backupCreated = false;
    if (fs.existsSync(targetPath)) {
      const backupPath = path.join(backupRoot, ...change.path.split('/'));
      fs.mkdirSync(path.dirname(backupPath), { recursive: true });
      fs.renameSync(targetPath, backupPath);
      backupCreated = true;
    }
    const committedChange: CommittedChange = {
      change,
      backupCreated,
      targetWritten: false,
    };
    transaction.committed.push(committedChange);

    if (change.action !== 'delete') {
      const stagedPath = path.join(stagedRoot, ...change.path.split('/'));
      fs.mkdirSync(path.dirname(targetPath), { recursive: true });
      fs.renameSync(stagedPath, targetPath);
      committedChange.targetWritten = true;
      transaction.written.push(targetPath);
    } else {
      transaction.removed.push(targetPath);
    }
  }
}

function publishPlanManifest(transaction: PlanTransaction): void {
  const { prepared, backupRoot, stagedRoot } = transaction;
  if (!prepared.manifestChanged) return;

  const manifestBackupPath = path.join(backupRoot, GENERATED_FILES_MANIFEST);
  if (fs.existsSync(prepared.publicPlan.manifestPath)) {
    fs.mkdirSync(path.dirname(manifestBackupPath), { recursive: true });
    fs.renameSync(prepared.publicPlan.manifestPath, manifestBackupPath);
    transaction.manifestBackupCreated = true;
  }

  if (prepared.manifestContent === undefined) return;
  const stagedManifestPath = path.join(stagedRoot, GENERATED_FILES_MANIFEST);
  fs.renameSync(stagedManifestPath, prepared.publicPlan.manifestPath);
  transaction.manifestPublished = true;
}

function rollbackTransaction(transaction: PlanTransaction): string[] {
  const errors: string[] = [];
  const attempt = (description: string, operation: () => void): void => {
    try {
      operation();
    } catch (error) {
      errors.push(
        `${description}: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  };
  const { prepared, backupRoot } = transaction;

  if (transaction.manifestPublished) {
    attempt('remove partially published ownership manifest', () => {
      if (fs.existsSync(prepared.publicPlan.manifestPath)) {
        fs.rmSync(prepared.publicPlan.manifestPath, { force: true });
      }
    });
  }
  const manifestBackupPath = path.join(backupRoot, GENERATED_FILES_MANIFEST);
  if (transaction.manifestBackupCreated) {
    attempt('restore previous ownership manifest', () => {
      if (!fs.existsSync(manifestBackupPath)) {
        throw new Error(`Backup is missing: ${manifestBackupPath}`);
      }
      fs.mkdirSync(path.dirname(prepared.publicPlan.manifestPath), {
        recursive: true,
      });
      fs.renameSync(manifestBackupPath, prepared.publicPlan.manifestPath);
    });
  }

  for (const committedChange of [...transaction.committed].reverse()) {
    const { change, backupCreated, targetWritten } = committedChange;
    if (targetWritten) {
      attempt(`remove partially written file ${change.absolutePath}`, () => {
        if (fs.existsSync(change.absolutePath)) {
          fs.rmSync(change.absolutePath, { force: true });
        }
      });
    }
    const backupPath = path.join(backupRoot, ...change.path.split('/'));
    if (backupCreated) {
      attempt(`restore previous file ${change.absolutePath}`, () => {
        if (!fs.existsSync(backupPath)) {
          throw new Error(`Backup is missing: ${backupPath}`);
        }
        fs.mkdirSync(path.dirname(change.absolutePath), { recursive: true });
        fs.renameSync(backupPath, change.absolutePath);
      });
    } else {
      attempt(`remove empty directories for ${change.absolutePath}`, () => {
        removeEmptyParents(
          path.dirname(change.absolutePath),
          prepared.publicPlan.outputDir
        );
      });
    }
  }

  return errors;
}

function resultForPrepared(
  prepared: PreparedPlan,
  overrides: Partial<WriteResult>
): WriteResult {
  return {
    success: true,
    filesWritten: [],
    filesRemoved: [],
    plan: prepared.publicPlan,
    planFingerprint: prepared.publicPlan.fingerprint,
    ...overrides,
  };
}

async function applyPreparedPlans(
  preparedPlans: PreparedPlan[],
  showProgress: boolean
): Promise<WriteBatchResult> {
  const allConflictErrors = preparedPlans.flatMap(({ publicPlan }) =>
    conflictErrors(publicPlan)
  );
  if (allConflictErrors.length > 0) {
    return {
      success: false,
      errors: allConflictErrors,
      results: preparedPlans.map((prepared) => {
        const errors = conflictErrors(prepared.publicPlan);
        return resultForPrepared(prepared, {
          success: errors.length === 0,
          ...(errors.length === 0 ? {} : { errors }),
        });
      }),
    };
  }

  const transactions: PlanTransaction[] = [];
  const total = preparedPlans.reduce(
    (count, prepared) =>
      count +
      prepared.publicPlan.changes.filter(
        (change) =>
          change.path !== GENERATED_FILES_MANIFEST &&
          (change.action === 'create' ||
            change.action === 'update' ||
            change.action === 'delete')
      ).length,
    0
  );
  const progress = { current: 0, total };

  try {
    for (const prepared of preparedPlans) {
      const hasWork =
        prepared.manifestChanged ||
        prepared.publicPlan.changes.some(
          (change) =>
            change.path !== GENERATED_FILES_MANIFEST &&
            (change.action === 'create' ||
              change.action === 'update' ||
              change.action === 'delete')
        );
      if (!hasWork) continue;
      const transaction = createPlanTransaction(prepared);
      transactions.push(transaction);
      stagePlan(transaction);
    }

    for (const transaction of transactions) {
      assertPlanStillCurrent(transaction);
    }
    for (const transaction of transactions) {
      commitPlanFiles(transaction, showProgress, progress);
    }
    // Every ownership manifest is published after every content mutation.
    for (const transaction of transactions) {
      publishPlanManifest(transaction);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const rollbackByPlan = new Map<GenerationPlan, string[]>();
    for (const transaction of [...transactions].reverse()) {
      rollbackByPlan.set(
        transaction.prepared.publicPlan,
        rollbackTransaction(transaction)
      );
    }

    for (const transaction of transactions) {
      const rollbackErrors = rollbackByPlan.get(
        transaction.prepared.publicPlan
      )!;
      if (rollbackErrors.length === 0) {
        try {
          fs.rmSync(transaction.transactionRoot, {
            recursive: true,
            force: true,
          });
        } catch (cleanupError) {
          rollbackErrors.push(
            `remove transaction directory: ${cleanupError instanceof Error ? cleanupError.message : 'Unknown error'}`
          );
        }
      }
    }

    const errors = [`Failed to apply generated file plans: ${message}`];
    return {
      success: false,
      errors,
      results: preparedPlans.map((prepared) => {
        const transaction = transactions.find(
          (candidate) => candidate.prepared === prepared
        );
        const rollbackErrors = rollbackByPlan.get(prepared.publicPlan) ?? [];
        return resultForPrepared(prepared, {
          success: false,
          errors,
          ...(rollbackErrors.length === 0
            ? {}
            : {
                rollbackErrors,
                recoveryPath: transaction?.transactionRoot,
              }),
        });
      }),
    };
  }

  // At this point every content change and ownership manifest is committed.
  // Cleanup cannot safely change that outcome: deleting one transaction's
  // backups and then rolling every root back would make earlier roots
  // unrestorable. Retain any transaction directory that cannot be removed and
  // report it as a warning instead.
  const cleanupWarningsByPlan = new Map<GenerationPlan, string[]>();
  for (const transaction of transactions) {
    for (const { change } of transaction.committed) {
      if (change.action === 'delete') {
        removeEmptyParents(
          path.dirname(change.absolutePath),
          transaction.prepared.publicPlan.outputDir
        );
      }
    }

    try {
      fs.rmSync(transaction.transactionRoot, {
        recursive: true,
        force: true,
      });
    } catch (cleanupError) {
      cleanupWarningsByPlan.set(transaction.prepared.publicPlan, [
        `Generated files were committed, but the transaction directory could not be removed: ${
          cleanupError instanceof Error ? cleanupError.message : 'Unknown error'
        }`,
      ]);
    }

    if (transaction.prepared.removeOutputDirWhenEmpty) {
      try {
        fs.rmdirSync(transaction.prepared.publicPlan.outputDir);
      } catch {
        // Unowned files or directories keep the output root alive.
      }
    }
  }

  const byPlan = new Map(
    transactions.map((transaction) => [
      transaction.prepared.publicPlan,
      transaction,
    ])
  );
  return {
    success: true,
    results: preparedPlans.map((prepared) => {
      const transaction = byPlan.get(prepared.publicPlan);
      const warnings = cleanupWarningsByPlan.get(prepared.publicPlan) ?? [];
      return resultForPrepared(prepared, {
        filesWritten: transaction?.written ?? [],
        filesRemoved: transaction?.removed ?? [],
        ...(warnings.length === 0
          ? {}
          : {
              warnings,
              recoveryPath: transaction?.transactionRoot,
            }),
      });
    }),
  };
}

/**
 * Plan and optionally apply generated files.
 *
 * Dry runs execute the same formatting, ownership, conflict, and pruning
 * decisions as a real write, but never create the output or transaction dirs.
 */
export async function writeGeneratedFiles(
  files: GeneratedFile[],
  outputDir: string,
  _subdirs: string[],
  options: WriteOptions = {}
): Promise<WriteResult> {
  const { dryRun, ...jobOptions } = options;
  const batch = await writeGeneratedFileJobs(
    [
      {
        files,
        outputDir,
        options: jobOptions,
      },
    ],
    {
      dryRun,
      showProgress: options.showProgress,
    }
  );
  return (
    batch.results[0] ?? {
      success: false,
      errors: batch.errors ?? ['Failed to prepare generated files.'],
    }
  );
}

function mergeWriteJobs(
  jobs: GeneratedFileWriteJob[]
): GeneratedFileWriteJob[] {
  const grouped = new Map<string, GeneratedFileWriteJob>();
  for (const job of jobs) {
    const outputDir = canonicalizeOutputDir(job.outputDir);
    const current = grouped.get(outputDir);
    if (!current) {
      grouped.set(outputDir, {
        files: [...job.files],
        outputDir,
        options: {
          ...(job.options ?? {}),
          adoptUnownedPaths: [...(job.options?.adoptUnownedPaths ?? [])],
        },
      });
      continue;
    }

    current.files.push(...job.files);
    current.options = {
      ...current.options,
      ...job.options,
      pruneStaleFiles:
        current.options?.pruneStaleFiles === true ||
        job.options?.pruneStaleFiles === true,
      removeManifestWhenEmpty:
        current.options?.removeManifestWhenEmpty === true ||
        job.options?.removeManifestWhenEmpty === true,
      adoptUnownedPaths: [
        ...(current.options?.adoptUnownedPaths ?? []),
        ...(job.options?.adoptUnownedPaths ?? []),
      ],
    };
  }
  return [...grouped.values()];
}

/**
 * Plan all output roots before mutating any of them, then stage and commit them
 * as one recoverable operation. Output roots may live on different filesystems;
 * each root stages locally and every committed root is rolled back if a later
 * root fails.
 */
export async function writeGeneratedFileJobs(
  jobs: GeneratedFileWriteJob[],
  options: WriteBatchOptions = {}
): Promise<WriteBatchResult> {
  if (options.signal?.aborted) {
    throw (
      options.signal.reason ??
      Object.assign(new Error('Operation cancelled.'), { name: 'AbortError' })
    );
  }
  let preparedPlans: PreparedPlan[];
  try {
    preparedPlans = await Promise.all(
      mergeWriteJobs(jobs).map((job) =>
        prepareGenerationPlan(job.files, job.outputDir, job.options ?? {})
      )
    );
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    return { success: false, results: [], errors: [message] };
  }

  if (options.signal?.aborted) {
    throw (
      options.signal.reason ??
      Object.assign(new Error('Operation cancelled.'), { name: 'AbortError' })
    );
  }

  if (options.dryRun) {
    const results = preparedPlans.map((prepared) => {
      const errors = conflictErrors(prepared.publicPlan);
      return resultForPrepared(prepared, {
        success: errors.length === 0,
        ...(errors.length === 0 ? {} : { errors }),
      });
    });
    const errors = results.flatMap((result) => result.errors ?? []);
    return {
      success: errors.length === 0,
      results,
      ...(errors.length === 0 ? {} : { errors }),
    };
  }

  return applyPreparedPlans(preparedPlans, options.showProgress ?? true);
}
